  $('#nav').innerHTML=groups.map(([t,i,n])=>`<button class="nav-item ${filter===t?'active':''}" data-filter="${t}" aria-label="${n}">${icon(i)}<span>${n}</span><span class="nav-count">${count(t)}</span></button>`).join('');
  $('#filters').innerHTML=groups.map(([t,i,n])=>`<button class="filter-tab ${filter===t?'active':''}" data-filter="${t}">${t==='pdf'?'PDF':t==='all'?'All files':n}<span>${count(t)}</span></button>`).join('');
