  $('#totalCount').textContent=files.length;$('#storageText').textContent=`${files.length} files · ${size(files.reduce((n,f)=>n+f.blob.size,0))}`;
  let shown=files.filter(f=>(filter==='all'||(filter==='textcode'?['text','html'].includes(f.type):f.type===filter))&&f.name.toLowerCase().includes(query.toLowerCase()));
  shown.sort((a,b)=>$('#sort').value==='name'?a.name.localeCompare(b.name):$('#sort').value==='size'?b.blob.size-a.blob.size:b.modified-a.modified);
  $('#fileList').innerHTML=shown.length?shown.map(f=>`<div class="file-row ${selected.has(f.id)?'selected':''}" data-id="${f.id}"><div class="file-main"><input type="checkbox" aria-label="Select ${esc(f.name)}" data-select="${f.id}" ${selected.has(f.id)?'checked':''}><button class="file-open" data-open="${f.id}"><span class="file-icon" style="${style(f.type)}">${icon(formats[f.type].icon)}</span><strong>${esc(f.name)}</strong></button></div><span class="type-tag" style="${style(f.type)}">${esc(f.name.split('.').pop().toUpperCase())}</span><span class="modified">${when(f.modified)}</span><span class="file-size">${size(f.blob.size)}</span><div class="row-actions"><button class="icon-button" data-download="${f.id}" title="Download ${esc(f.name)}" aria-label="Download ${esc(f.name)}">${icon('download')}</button><button class="icon-button" data-delete="${f.id}" title="Delete ${esc(f.name)}" aria-label="Delete ${esc(f.name)}">${icon('trash')}</button></div></div>`).join(''):`<div class="empty-state"><span class="empty-icon">${icon(query?'search':'folder')}</span><h3>${query?'No matching files':files.length?'A little room for something new.':'A clear desk. A fresh start.'}</h3><p>${query?'Try a different name or another file type.':'Add a file or create something from scratch.'}</p><button class="text-link" id="emptyCreate">${query?'Clear search':'Create your first file'} →</button></div>`;
  $('#fileCount').textContent=`${shown.length} ${shown.length===1?'file':'files'}${query?' found':''}`;
  const validSelected=[...selected].filter(id=>files.some(f=>f.id===id));selected=new Set(validSelected);
  $('#selectionBar').hidden=!selected.size;$('#selectionBar').className='selection-bar';$('#selectionBar').innerHTML=`<span>${selected.size} selected</span><button id="zipSelected">${icon('zip')} Create ZIP</button><button id="deleteSelected">Delete</button><button id="clearSelected">Clear</button>`;
  $('#selectAll').checked=shown.length>0&&shown.every(f=>selected.has(f.id));$('#selectAll').indeterminate=shown.some(f=>selected.has(f.id))&&!$('#selectAll').checked;
  $$('#nav [data-filter], #filters [data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;selected.clear();render()});
  $$('[data-open]').forEach(b=>b.onclick=()=>run(()=>openFile(b.dataset.open)));
  $$('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(b.dataset.select):selected.delete(b.dataset.select);render()});
  $$('[data-download]').forEach(b=>b.onclick=()=>{const f=files.find(f=>f.id===b.dataset.download);download(f.blob,f.name)});
  $$('[data-delete]').forEach(b=>b.onclick=()=>askDelete([b.dataset.delete]));
