  $('#prevPage').onclick=()=>run(async()=>{if(editorState.page>0){await editorState.textController?.applyDraft();editorState.page--;await renderPDF()}});$('#nextPage').onclick=()=>run(async()=>{if(editorState.page<editorState.pageCount-1){await editorState.textController?.applyDraft();editorState.page++;await renderPDF()}});
  $('#pdfRotate').onclick=()=>run(()=>mutatePDF(doc=>{const p=doc.getPage(editorState.page);p.setRotation(PDFLib.degrees((p.getRotation().angle+90)%360))}));
  $('#pdfAdd').onclick=()=>run(()=>mutatePDF(doc=>{doc.insertPage(editorState.page+1,PDFLib.PageSizes.A4);editorState.page++}));
  $('#pdfDelete').onclick=()=>run(()=>mutatePDF(doc=>{if(doc.getPageCount()===1)throw Error('Keep at least one page in your PDF.');doc.removePage(editorState.page);editorState.page=Math.min(editorState.page,doc.getPageCount()-1)}));
