  $('#pdfMerge').onclick=()=>$('#mergeInput').click();$('#pdfUndo').onclick=()=>run(async()=>{if(!editorState.history.length)return;editorState.pdfBytes=editorState.history.pop();active.blob=new Blob([editorState.pdfBytes],{type:'application/pdf'});await persist(active);await renderPDF()});
  $('#pdfJpeg').onclick=()=>run(async()=>{download(await canvasBlob($('#pdfCanvas')),active.name.replace(/\.pdf$/i,`-page-${editorState.page+1}.jpg`));toast('Page exported as JPEG')});
  const overlay=$('#pdfOverlay');let start;
  overlay.onpointerdown=e=>{if(editorState.busy)return;const r=overlay.getBoundingClientRect();start={x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};overlay.setPointerCapture(e.pointerId)};
  overlay.onpointermove=e=>{if(!start||editorState.mode!=='cover')return;const r=overlay.getBoundingClientRect(),ctx=overlay.getContext('2d'),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;ctx.clearRect(0,0,overlay.width,overlay.height);ctx.fillStyle='#e3653c33';ctx.strokeStyle='#e3653c';ctx.lineWidth=2;ctx.fillRect(start.x*overlay.width,start.y*overlay.height,(x-start.x)*overlay.width,(y-start.y)*overlay.height);ctx.strokeRect(start.x*overlay.width,start.y*overlay.height,(x-start.x)*overlay.width,(y-start.y)*overlay.height)};
  overlay.onpointerup=e=>{if(!start)return;const r=overlay.getBoundingClientRect(),end={x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))},s=start;start=null;overlay.getContext('2d').clearRect(0,0,overlay.width,overlay.height);run(async()=>{if(editorState.mode==='text'){const text=$('#annotationText').value;if(!text.trim()){toast('Type your text in the sidebar first');$('#annotationText').focus();return}const fontsize=Number($('#annotationSize').value);if(!Number.isFinite(fontsize)||fontsize<6||fontsize>150)throw Error('Choose a text size from 6 to 150.');const temp=document.createElement('canvas'),ctx=temp.getContext('2d');ctx.font=`${fontsize*2}px sans-serif`;const lines=text.split('\n');temp.width=Math.min(16384,Math.ceil(Math.max(...lines.map(l=>ctx.measureText(l).width)))+12);temp.height=Math.ceil(fontsize*2*1.4*lines.length);ctx.font=`${fontsize*2}px sans-serif`;ctx.fillStyle=$('#annotationColor').value;ctx.textBaseline='top';lines.forEach((l,i)=>ctx.fillText(l,4,i*fontsize*2*1.4,temp.width-8));const png=temp.toDataURL('image/png');await drawOnPDF(async(d,p,transform)=>{const im=await d.embedPng(png);const w=temp.width/2,h=temp.height/2;transform.image(im,s.x,s.y,w,h)})}else{const w=Math.abs(s.x-end.x),h=Math.abs(s.y-end.y);if(w<.005||h<.005)return;await drawOnPDF((d,p,t)=>t.rect(Math.min(s.x,end.x),Math.min(s.y,end.y),w,h))}})};
