  editorState.textController=createPDFTextController({getBytes:()=>editorState.pdfBytes,getPage:()=>editorState.page,getPassword:()=>editorState.pdfPassword||'',commit:commitPDFTextEdit,beginBusy,endBusy,toast,onMode:setPDFMode});
  setPDFMode('edit');
